package br.com.bancohorizonte.repository; import br.com.bancohorizonte.entity.TipoConta; import jakarta.persistence.*; import java.util.*;
public class TipoContaRepository { private final EntityManager em; public TipoContaRepository(EntityManager em){this.em=em;} public Optional<TipoConta> porId(Long id){return Optional.ofNullable(em.find(TipoConta.class,id));} public Optional<TipoConta> porNome(String nome){TypedQuery<TipoConta> q=em.createQuery("select t from TipoConta t where t.nome = :nome",TipoConta.class);return q.setParameter("nome",nome).getResultStream().findFirst();} }
